    internal static string Fixture(DateTimeOffset now)=>JsonSerializer.Serialize(new{
        timestamp=now,fissures=Array.Empty<object>(),alerts=Array.Empty<object>(),cetusCycle=new{state="day",expiry=now.AddMinutes(20)},earthCycle=new{state="night",expiry=now.AddHours(4)},
        vallisCycle=new{state="cold",expiry=now.AddMinutes(10)},cambionCycle=new{state="fass",expiry=now.AddMinutes(20)},
        zarimanCycle=new{state="grineer",expiry=now.AddMinutes(90)},duviriCycle=new{state="envy",expiry=now.AddMinutes(60)},
        arbitration=new{nodeKey="SolNode000",typeKey="Unknown",activation="1970-01-01T00:00:00Z",expiry="+275760-09-13T00:00:00.000Z"}});
