    private static string Official(DateTimeOffset at,DateTimeOffset nightEnd)=>JsonSerializer.Serialize(new{Time=at.ToUnixTimeSeconds(),SyndicateMissions=new[]{new{Tag="CetusSyndicate",Expiry=new Dictionary<string,object>{{"$date",new Dictionary<string,string>{{"$numberLong",nightEnd.ToUnixTimeMilliseconds().ToString()}}}}}}});
    internal static void Run(Action<string,Action> check)
