        var c=ScheduleCatalog.Load();var table=ArbitrationSchedule.Bundled(c);var now=DateTimeOffset.Parse("2026-10-26T00:00:00Z");
        void Yes(bool b,string reason="조건 불일치"){if(!b)throw new Exception(reason);}
        void Reject(string text){try{ArbitrationSchedule.Parse(text,now,"test");}catch(InvalidDataException){return;}throw new Exception("잘못된 일정표 수락");}
        check("일정: 전체 노드·상점 내부 ID 연결과 한국어 분류",()=>{Yes(c.Nodes.Length==88&&c.Offers.Length==19);Yes(table.Slots.All(s=>c.Nodes.Any(n=>n.Id==s.NodeId)));Yes(c.Nodes.All(n=>n.Planet.Any(ch=>ch>='가'&&ch<='힣')&&n.Mission.Any(ch=>ch>='가'&&ch<='힣')));var all=InventoryCatalog.Load().Items.Select(i=>i.Id).ToHashSet();Yes(c.Offers.All(w=>all.Contains(w.Id)));});
        check("일정: 상점19종 모두 현재 모딩 카탈로그에 ID 연결",()=>{var ids=Catalog.Load().Weapons.Select(w=>w.Id).Concat(ReferenceCatalog.Load().Weapons.Select(w=>w.InternalId)).ToHashSet();Yes(c.Offers.All(w=>ids.Contains(w.Id)));});
        check("일정: 커뮤니티 S티어 5노드 고정 출처",()=>Yes(c.Nodes.Where(n=>n.Tier=="S").Select(n=>n.Id).Order().SequenceEqual(new[]{"SolNode106","SolNode25","SolNode450","SolNode64","SolNode719"})));
        check("일정: 미션·팩션 AND 필터와 혼합 진영 노드",()=>
        {var mixed=c.Nodes.Single(n=>n.Id=="SolNode450");Yes(new ArbitrationFilter("S","거울상 방어","그리니어").Matches(mixed)&&new ArbitrationFilter("S","거울상 방어","코퍼스").Matches(mixed));Yes(!new ArbitrationFilter("S","생존","코퍼스").Matches(mixed)&&!new ArbitrationFilter("S","거울상 방어","인페스티드").Matches(mixed));Yes(table.NextS(c,now,new("S","거울상 방어","코퍼스"))!.NodeId=="SolNode450"&&table.NextS(c,now,new("S","생존","코퍼스")) is null);});
        check("일정: 44056개 연속 1시간 슬롯·유한 예측 구간",()=>{Yes(table.Slots.Length==44056);Yes(table.Slots.Zip(table.Slots.Skip(1)).All(x=>x.Second.StartUtc-x.First.StartUtc==TimeSpan.FromHours(1)));Yes(table.Current(table.Slots[^1].EndUtc) is null&&table.NextS(c,table.Slots[^1].EndUtc) is null&&!table.Window(table.Slots[^1].EndUtc,24).Any());});
        check("일정: 2026-10-26 03UTC Callisto·현재와 다음 S 분리",()=>{var next=table.NextS(c,now)!;Yes(next.StartUtc==now.AddHours(3)&&next.NodeId=="SolNode25");Yes(table.Current(next.StartUtc)?.NodeId==next.NodeId&&table.NextS(c,next.StartUtc)!.StartUtc>next.StartUtc);Yes(table.Current(next.EndUtc)!.StartUtc==next.EndUtc);});
        check("일정: 기간 끝은 제외·지나간 구간 반복 금지",()=>{var rows=table.Window(now.AddMinutes(30),24).ToArray();Yes(rows[0].StartUtc==now&&rows[^1].StartUtc==now.AddHours(24));Yes(!table.Window(table.Slots[0].StartUtc.AddHours(-24),1).Any());});
        check("일정: 누락·역순·중복·빈 ID·범위 밖 epoch 거부",()=>{string Csv(Func<int,string> f)=>string.Join('\n',Enumerable.Range(0,24).Select(f));foreach(var bad in new[]{Csv(i=>$"{now.ToUnixTimeSeconds()+i*3600},"),Csv(i=>$"{long.MaxValue},SolNode25"),Csv(i=>$"{now.ToUnixTimeSeconds()+(i==12?11:i)*3600},SolNode25"),Csv(i=>$"{now.ToUnixTimeSeconds()+i*7200},SolNode25"),"1,SolNode25"})Reject(bad);});
        check("일정: KST 자정 변환·음수 카운트다운 방지",()=>{Yes(WorldScheduleEngine.KoreaTime(DateTimeOffset.Parse("2026-10-25T15:00:00Z")).StartsWith("10-26 (월) 00:00"));Yes(WorldScheduleEngine.Countdown(now.AddSeconds(-1),now)=="00:00:00");Yes(WorldScheduleEngine.Countdown(now.AddDays(1).AddSeconds(.1),now)=="1일 00:00:01");});
        check("일정: API 구식 지구4시간·무효 중재 무시",()=>{var s=Snapshot(now);Yes(s.Cycles.Length==5&&!s.Cycles.Any(c=>c.Id=="earthCycle")&&s.LiveArbitrationNode is null);var d=WorldScheduleEngine.Definitions.Single(d=>d.Id=="cetusCycle");Yes(d.Seconds.SequenceEqual(new[]{6000,3000}));});
        check("일정: 지연 API를 공식 평원·캠비온 기준으로만 보완",()=>
        {var stale=Snapshot(now.AddMinutes(-20));using var raw=JsonDocument.Parse(Official(now,now.AddMinutes(60).AddSeconds(55)));var s=WorldScheduleEngine.WithOfficialCycles(stale,raw.RootElement);var d=new WorldScheduleData(s,table,false,null,now);var cetus=s.Cycles.Single(c=>c.Id=="cetusCycle");Yes(cetus.State=="day"&&cetus.ExpiryUtc==now.AddMinutes(10).AddSeconds(55)&&cetus.Source=="공식 월드 상태"&&d.CycleFresh(cetus,now));Yes(!d.Fresh(now)&&!d.CycleFresh(s.Cycles.Single(c=>c.Id=="vallisCycle"),now),"다른 지역·중재의 오래된 시각을 새 시각으로 세탁하면 안 됨");Yes(s.Cycles.Single(c=>c.Id=="cambionCycle").SourceUtc==now);});
        check("일정: 공식 낮·밤 경계·만료된 의뢰 기준 거부",()=>
        {using var raw=JsonDocument.Parse(Official(now,now.AddMinutes(50)));var s=WorldScheduleEngine.WithOfficialCycles(null,raw.RootElement);Yes(s.Cycles.Single(c=>c.Id=="cetusCycle").State=="night");using var old=JsonDocument.Parse(Official(now,now.AddSeconds(-1)));bool rejected=false;try{WorldScheduleEngine.WithOfficialCycles(null,old.RootElement);}catch(InvalidDataException){rejected=true;}Yes(rejected);});
        check("일정: 평원 낮→밤 정확 경계·저장자료 반복 예상",()=>{var a=new CycleAnchor("cetusCycle","day",now.AddMinutes(100));Yes(WorldScheduleEngine.CycleAt(a,now)!.Label=="낮");Yes(WorldScheduleEngine.CycleAt(a,now.AddMinutes(100))!.Label=="밤");Yes(WorldScheduleEngine.CycleAt(a,now.AddMinutes(150))!.Label=="낮");Yes(WorldScheduleEngine.CycleAt(a,now.AddMinutes(300))!.Projected);Yes(WorldScheduleEngine.NextState(a,"night",now)!.StartUtc==now.AddMinutes(100));});
        check("일정: 오브 협곡 따뜻함400초·추움1200초",()=>{var a=new CycleAnchor("vallisCycle","warm",now.AddSeconds(400));var p=WorldScheduleEngine.CycleAt(a,now.AddSeconds(400))!;Yes(p.State=="cold"&&p.EndUtc==now.AddSeconds(1600));Yes(WorldScheduleEngine.CycleAt(a,now.AddSeconds(1600))!.State=="warm");});
        check("일정: 자리만150분·두비리 나선 순서10시간 주기",()=>{var a=new CycleAnchor("zarimanCycle","corpus",now.AddMinutes(150));Yes(WorldScheduleEngine.CycleAt(a,now.AddMinutes(150))!.State=="grineer");var b=new CycleAnchor("duviriCycle","sorrow",now.AddHours(2));Yes(Enumerable.Range(0,6).Select(i=>WorldScheduleEngine.CycleAt(b,now.AddHours(2*i))!.State).SequenceEqual(new[]{"sorrow","fear","joy","anger","envy","sorrow"}));});
        check("일정: 시계 역행·잘못된 상태·오래된 자료 구분",()=>{Yes(WorldScheduleEngine.CycleAt(new("vallisCycle","warm",now.AddMinutes(10)),now) is null);Yes(WorldScheduleEngine.CycleAt(new("vallisCycle","oops",now),now) is null);Yes(!WorldScheduleEngine.Fresh(Snapshot(now.AddMinutes(-11)),now));Yes(!WorldScheduleEngine.Fresh(Snapshot(now.AddMinutes(3)),now));});
        check("일정: 테넷4일00UTC·코다 A/B 경계",()=>{var a=WorldScheduleEngine.ShopAt(c,"coda",c.CodaEpoch);Yes(a.Batch=="A"&&a.StartUtc==c.CodaEpoch&&a.EndUtc==c.CodaEpoch.AddDays(4));Yes(WorldScheduleEngine.ShopAt(c,"coda",a.EndUtc).Batch=="B");Yes(WorldScheduleEngine.ShopAt(c,"coda",c.CodaEpoch.AddTicks(-1)).Batch=="B");var t=WorldScheduleEngine.ShopAt(c,"tenet",now);Yes(t.EndUtc-t.StartUtc==TimeSpan.FromDays(4)&&t.StartUtc.Hour==0);Yes(WorldScheduleEngine.ShopAt(c,"tenet",t.EndUtc).StartUtc==t.EndUtc);});
        check("일정: 테넷5개40홀로키·코다7+7개10심장세포",()=>{Yes(c.Offers.Count(w=>w.Shop=="tenet"&&w.Price==40)==5);Yes(c.Offers.Count(w=>w.Batch=="A"&&w.Price==10)==7&&c.Offers.Count(w=>w.Batch=="B"&&w.Price==10)==7);Yes(c.Offers.Single(w=>w.EnglishName=="Coda Bubonico").Batch=="B");});
        check("일정: 무기별 현재 회차·다음 코다 판매 구분",()=>{var w=WorldScheduleEngine.ShopAt(c,"coda",now);foreach(var gun in c.Offers.Where(x=>x.Shop=="coda"))Yes(WorldScheduleEngine.WeaponNextStart(gun,w)==(gun.Batch==w.Batch?w.StartUtc:w.EndUtc));});
        var target=c.Offers.First(w=>w.Shop=="tenet");string Row(double n,string e="Heat")=>$"<table><th>Bonus %</th><tr><td>{{{{Weapon|{target.EnglishName}}}}}</td><td>{{{{D|{e}}}}}</td><td>{{{{ValenceBonusPercentageColor|{n.ToString(System.Globalization.CultureInfo.InvariantCulture)}}}}}</td></tr></table>";
        check("일정: 위키 제보 수치 파싱·불가능 원소/25~60 밖 거부",()=>{Yes(VendorReportParser.Values(Row(57.6),c,"tenet","")[target.Id].Percent==57.6);Yes(VendorReportParser.Values(Row(80),c,"tenet","").Count==0&&VendorReportParser.Values(Row(50,"Viral"),c,"tenet","").Count==0);Yes(VendorReportParser.Values(Row(50)+Row(50)+Row(50),c,"tenet","").Count==0);});
        check("일정: 다른 문서 편집만으로 현회차 보너스 확정 금지",()=>{var w=WorldScheduleEngine.ShopAt(c,"tenet",now);var date=w.StartUtc.AddMinutes(10);Yes(!VendorReportParser.Compare(c,w,Row(50),date,1,Row(50),date).Bonuses.Single().ChangedThisRotation);Yes(VendorReportParser.Compare(c,w,Row(51),date,1,Row(50),date).Bonuses.Single().ChangedThisRotation);Yes(!VendorReportParser.Compare(c,w,Row(51),w.StartUtc.AddSeconds(-1),1,Row(50),date).Bonuses.Single().ChangedThisRotation);Yes(!VendorReportParser.Compare(c,w,Row(51),date,1,null,date).Bonuses.Single().ChangedThisRotation);});
        check("일정: 알림 기본끔·중복·예측 불일치 차단",()=>{var start=table.NextS(c,now)!.StartUtc;var t=start.AddMinutes(-3);var fresh=ArbitrationSchedule.Parse(string.Join('\n',table.Slots.Select(s=>$"{s.StartUtc.ToUnixTimeSeconds()},{s.NodeId}")),t,"test");var d=new WorldScheduleData(Snapshot(t),fresh,false,null,t);Yes(ScheduleAlerts.Due(c,d,new(),t,new HashSet<string>()).Length==0);var alerts=ScheduleAlerts.Due(c,d,new(NextS:true),t,new HashSet<string>());Yes(alerts.Length==1);Yes(ScheduleAlerts.Due(c,d,new(NextS:true),t,alerts.Select(a=>a.Id).ToHashSet()).Length==0);var conflict=d with{Snapshot=d.Snapshot! with{LiveArbitrationNode="wrong",LiveArbitrationStart=t.AddMinutes(-1),LiveArbitrationEnd=t.AddMinutes(10)}};Yes(conflict.ArbitrationConflict(t)&&ScheduleAlerts.Due(c,conflict,new(NextS:true),t,new HashSet<string>()).Length==0);});
        check("일정: 주기 API 실패 시 캐시 보존·분당 요청 제한·재시작",()=>
        {
            string dir=Path.Combine(Path.GetTempPath(),"wf-schedule-"+Guid.NewGuid());Directory.CreateDirectory(dir);
            try{var at=DateTimeOffset.UtcNow;var csv=string.Join('\n',table.Slots.Select(s=>$"{s.StartUtc.ToUnixTimeSeconds()},{s.NodeId}"));var handler=new Handler((request,n)=>n<=2?new(HttpStatusCode.OK){Content=new StringContent(request.RequestUri!.Host.Contains("github")?csv:Fixture(at),Encoding.UTF8)}:new(HttpStatusCode.ServiceUnavailable));using var client=new WorldScheduleClient(dir,handler);var first=client.RefreshAsync(true,default).GetAwaiter().GetResult();Yes(first.Fresh(at)&&client.RequestCount==2);client.RefreshAsync(false,default).GetAwaiter().GetResult();Yes(client.RequestCount==2);var failed=client.RefreshAsync(true,default).GetAwaiter().GetResult();Yes(failed.Cached&&failed.Snapshot==first.Snapshot&&failed.Notice!.Contains("갱신 실패"));using var restart=new WorldScheduleClient(dir,new Handler((r,n)=>new(HttpStatusCode.ServiceUnavailable)));Yes(restart.Current.Cached&&restart.Current.Snapshot!.Cycles.Length==5&&restart.Current.Arbitrations.Current(at) is not null);}
            finally{Directory.Delete(dir,true);}
        });
        check("일정: 실제 클라이언트 공식 보완·혼합 기준 저장/재시작",()=>
        {
            var dir=Path.Combine(Path.GetTempPath(),"wf-official-"+Guid.NewGuid());try{var at=DateTimeOffset.UtcNow;var csv=string.Join('\n',table.Slots.Select(s=>$"{s.StartUtc.ToUnixTimeSeconds()},{s.NodeId}"));using var client=new WorldScheduleClient(dir,new Handler((r,n)=>new(HttpStatusCode.OK){Content=new StringContent(r.RequestUri!.Host.Contains("github")?csv:r.RequestUri.Host=="api.warframe.com"?Official(at,at.AddMinutes(60)):Fixture(at.AddMinutes(-20)))}));var d=client.RefreshAsync(true,default).GetAwaiter().GetResult();Yes(client.RequestCount==3&&d.CycleFresh(d.Snapshot!.Cycles.Single(c=>c.Id=="cetusCycle"),at));using var restart=new WorldScheduleClient(dir,new Handler((r,n)=>new(HttpStatusCode.ServiceUnavailable)));Yes(restart.Current.Snapshot!.Cycles.Single(c=>c.Id=="cetusCycle").Source=="공식 월드 상태"&&restart.Current.Cached);}
            finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}
        });
