    private sealed class Handler(Func<HttpRequestMessage,int,HttpResponseMessage> response):HttpMessageHandler
    {private int calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken t)=>Task.FromResult(response(r,++calls));}
